<?php
 namespace ehr; interface iPatientResourceItem extends iResourceItemMan { } class PatientResourceItem extends ResourceItemMan implements iPatientResourceItem { private const LINK_ATTR_PATIENT = 'Patient'; private const PHONE_TYPE = [ 'home', 'work', 'mobile' ]; private $sex = ''; private $dateOfBirth = ''; private $barcode = ''; private $outReason = 0; private $addressReside = ''; private $addressRegistration = ''; private $phoneList = []; private $numberHistory = ''; private $barState = 0; private $isLocal = false; private $enterpriseGUID = ''; public function __construct(Resource $aResource) { parent::__construct($aResource); } public function __destruct() { unset($this->phoneList); } public function getNumberHistory(): string { return $this->numberHistory; } public function getBarcode(): string { return $this->barcode; } public function getIsLocal(): bool { return $this->isLocal; } public function getBarState(): int { return $this->barState; } public function setBarState(int $state): void { $this->barState = $state; } public function getEnterpriseGUID(): string { return $this->enterpriseGUID; } public function setEnterpriseGUID(string $guid): void { $this->enterpriseGUID = $guid; } public function getProfileSDvalue(): string { return LinkSetup::ID_URL_SD_PATIENT; } public function clearResourceItem(): void { parent::clearResourceItem(); $this->sex = ''; $this->dateOfBirth = ''; $this->barcode = ''; $this->outReason = 0; $this->addressReside = ''; $this->addressRegistration = ''; array_splice($this->phoneList, 0); $this->numberHistory = ''; $this->barState = 0; $this->isLocal = false; $this->enterpriseGUID = ''; } private function setPhoneList(string $list): void { if (empty($list)) { return; } array_splice($this->phoneList, 0); $arr = safe_explode(PatientLink::PHONE_LIST_DELIMITER, $list); foreach ($arr as $el) { if (safe_strlen($el) >= 3) { $this->phoneList[] = [ substr($el, 0, 1), substr($el, 2) ]; } } } public function initData(array $record): void { parent::initData($record); $resource = $this->getResource(); $this->sex = $record['sex'] ?? ''; $this->dateOfBirth = $record['dateOfBirth'] ?? ''; $this->barcode = $record['barcode'] ?? ''; if (!empty($this->pin) && !empty($this->errorPersonalNumber)) { $resource->getLink()->getLogger()->addLog( "; пациент, а/к {$this->getNumberHistory()}, key: {$this->getId()}", '', Logger::LMT_WARN, true ); $this->pin = ''; } $this->outReason = $record['outReason'] ?? 0; $this->addressReside = $record['addressReside'] ?? ''; $this->addressRegistration = $record['addressRegistration'] ?? ''; $this->numberHistory = $record['numberHistory'] ?? ''; $this->state = $record['medPatientState'] ?? 0; $this->barState = $record['medPatientBarState'] ?? 0; $this->setPhoneList($record['phoneList']); $this->isLocal = (bool) $record['isLocal']; $this->setEnterpriseGUID($resource->getLs()->getParam('enterpriseFHIR')); } public function initJSONbase(): void { parent::initJSONbase(); LinkJSON::addNode($this->json, 'resourceType', self::LINK_ATTR_PATIENT); if (!empty($this->getBarcode())) { LinkJSON::addIdentifierV($this->json, LinkSetup::ID_URL_BAR, $this->getBarcode()); } if (!empty($this->getPIN())) { LinkJSON::addIdentifierV($this->json, LinkSetup::ID_URL_PIN, $this->getPIN()); } $this->addFIONode($this->json); LinkJSON::addNodeEx($this->json, 'gender', $this->sex); LinkJSON::addNodeEx($this->json, 'birthDate', $this->dateOfBirth); LinkJSON::addNodeEx($this->json, 'deceasedBoolean', $this->outReason === 4 ? 'true' : 'false'); if (!empty($this->addressRegistration)) { $this->addAddressNode($this->addressRegistration); } if (!empty($this->addressReside) && $this->addressReside !== $this->addressRegistration) { $this->addAddressNode($this->addressReside, 'temp'); } $telecom = &LinkJSON::addNode($this->json, 'telecom'); foreach ($this->phoneList as $el) { $telecom_el = LinkJSON::addNodeElement($telecom); LinkJSON::addNodeEx($telecom_el, 'system', 'phone'); LinkJSON::addNodeEx($telecom_el, 'value', $el[1]); if (in_array($el[0], [1, 2, 3])) { LinkJSON::addNodeEx($telecom_el, 'use', self::PHONE_TYPE[$el[0]]); } } LinkJSON::addNodeEx($this->json, 'active', 'true'); } private function addAddressNode(string $address, string $use = 'home'): void { $addr = &LinkJSON::addNode($this->json, 'address'); $el_addr = LinkJSON::addNodeElement($addr); $extension = &LinkJSON::addNode($el_addr, 'extension'); $el_extesion = LinkJSON::addNodeElement($extension); LinkJSON::addNodeEx($el_extesion, 'url', LinkSetup::ID_URL_SD_ADDR); LinkJSON::addCodeableConceptC($el_extesion, 'valueCodeableConcept', LinkSetup::ID_URL_VS_ADDR, 'location'); LinkJSON::addNodeEx($el_addr, 'use', $use); LinkJSON::addNodeEx($el_addr, 'text', $address); } public function appendJSON(): void { parent::appendJSON(); if (!empty($this->getGUID())) { LinkJSON::addNodeEx($this->json, 'id', $this->getGUID()); } if (!empty($this->getVersionGUID())) { $node = &LinkJSON::addNode($this->json, 'meta'); LinkJSON::addNodeEx($node, 'versionId', $this->getVersionGUID()); } $node = &LinkJSON::addNode($this->json, 'managingOrganization'); LinkJSON::addNodeEx($node, 'reference', "Organization/{$this->getEnterpriseGUID()}"); } private function addReferencePatient(\stdClass &$node, string $name): void { if (empty($this->getGUID())) { throw new Exception($this->makeReferenceErrorMessage(self::MSG_ERROR_PATIENT)); } $this->addSubReference($node, $name, self::LINK_ATTR_PATIENT); } } 